function handleSetTop(){let n=$("#overview-table-header").height();$("#overview-table-total > th").css({top:`${submenuHeight+n}px`})}function handleScroll(){if(window.innerWidth<supportMinWidth)$("#details-section-menu").removeClass("details-section-sticky");else{let n=$("#details-section").offset().top;window.pageYOffset>=n?$("#details-section-menu").addClass("details-section-sticky"):$("#details-section-menu").removeClass("details-section-sticky")}}function handleResize(){handleScroll();handleSetTop()}window.onscroll=handleScroll;window.addEventListener("resize",handleResize);$(document).ready(handleSetTop);